import React from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
  useMediaQuery,
  ListItem,
  FormGroup,
} from '@mui/material';
import { IPrivilege } from '../../../core/Interface/company.interface';
import { theme } from '../../../theme';
import CheckBoxIcon from '@mui/icons-material/CheckBox';

interface PrivilegeProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  data?: IPrivilege[];
}

const Privileges: React.FC<PrivilegeProps> = ({ open, setOpen, data }) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const handleClose = () => {
    setOpen(false);
  };

  return (
    <Dialog
      aria-labelledby="privileges"
      fullScreen={isMobile}
      fullWidth
      maxWidth="sm"
      onClose={handleClose}
      open={open}
    >
      <DialogTitle
        id="privileges"
        sx={{
          fontWeight: 600,
          background: '#CFD8DC',
          borderRadius: 1,
          padding: '16px 24px',
        }}
      >
        Company Admin User Privileges
      </DialogTitle>
      <DialogContent
        sx={{
          display: 'grid',
          gap: 1,
          alignItems: 'center',
          padding: '10px 20px',
          mt: 2,
        }}
      >
        {data ? (
          <FormGroup>
            {data.map((item, index) => (
              <ListItem
                key={index}
                sx={{ gap: '50px' }}
              >
                <CheckBoxIcon />
                <Typography>{item.privilege}</Typography>
              </ListItem>
            ))}
          </FormGroup>
        ) : (
          <Typography variant="body1">No Privileges Available</Typography>
        )}
      </DialogContent>
      <DialogActions sx={{ padding: '16px 24px' }}>
        <Button
          color="primary"
          onClick={handleClose}
          sx={{
            width: 200,
            height: 42,
            borderRadius: '5px',
            fontWeight: 'bold',
          }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default Privileges;
